import lxml.etree
from itertools import chain
import re
from robot.api import logger
from robot.libraries.BuiltIn import BuiltIn


class XMLTools(object):
    def change_mme_address(self, scfc_src, scfc_dst, new_ip, host_bts_name=None):
        """
        Changes MME IP address and BTS hostname
        :param scfc_src: Source SCFC file
        :param scfc_dst: Destination SCFC file
        :param host_bts_name: New BTS hostname
        :param new_ip: New MME IP
        :return: None
        """
        tree = lxml.etree.parse(scfc_src)
        root = tree.getroot()
        for elem in root.findall("*{*}managedObject/{*}p[@name=\"ipAddrPrim\"]"):
            elem.text = new_ip
        for elem in root.findall("*{*}managedObject/{*}p[@name=\"btsName\"]"):
            if host_bts_name is not None:
                elem.text = host_bts_name
        tree.write(scfc_dst)

    def _get_sw_version_from_radio(self, targetbd, radio_found):
        tree = lxml.etree.parse(targetbd)
        root = tree.getroot()
        pattern = "LTX_" + radio_found + ".*"
        elem_found = []
        for element in root.findall('hwResource'):
            if re.match(pattern, element.attrib["resourceBuildKey"]):
                elem_found.append(element.get("resourceSWVersion"))

        if not elem_found:
            raise ValueError("Radio {0} not found in targetBD file {1}".format(radio_found, targetbd))
        else:
            return elem_found[0]

    def _get_sw_file_key_from_radio(self, targetbd, radio_found):
        tree = lxml.etree.parse(targetbd)
        root = tree.getroot()
        pattern = "LTX_" + radio_found + ".*"
        elem_found = []
        for element in root.findall('hwResource'):
            if re.match(pattern, element.attrib["resourceBuildKey"]):
                swFileKey = element.find('swFileKey').text
                elem_found.append(swFileKey.replace(("LTX_" + radio_found + "_"), ""))
        if not elem_found:
            raise ValueError("Radio {0} not found in targetBD file {1}".format(radio_found, targetbd))
        else:
            return elem_found[0]

    def change_iphy_xml(self, iphy_src, iphy_dst, targetbd, change_sw_file_key=None):  # noqa: C901
        """
        Changes sw version in iphy.xml accrding to targetbd file.
        :param iphy_src: Source iphy.xml
        :param iphy_dst: Destination iphy.xml
        :param targetbd: TargetBD file
        :return: None
        """
        tree = lxml.etree.parse(iphy_src)
        root = tree.getroot()

        for tag in chain(root.iter('{*}resourceBuildKey'), root.iter('{*}productname')):
            if "LTX_" in tag.text:
                resourceswversion = self._get_sw_version_from_radio(targetbd, tag.text[4:])
                if change_sw_file_key:
                    swFileKey = self._get_sw_file_key_from_radio(targetbd, tag.text[4:])
            else:
                resourceswversion = self._get_sw_version_from_radio(targetbd, tag.text)
                if change_sw_file_key:
                    swFileKey = self._get_sw_file_key_from_radio(targetbd, tag.text)
            try:
                tag.getparent().find('{*}buildname').text = resourceswversion
            except AttributeError:
                tag.getparent().find('{*}bldVersion').text = resourceswversion

            if change_sw_file_key:
                for soap_config in tag.getparent().getparent().findall('soap-config'):
                    for name in soap_config.find('software').findall('file'):
                        name.find('name').text = swFileKey
                        name.find('version').text = resourceswversion

        tree.write(iphy_dst)

    def change_vlanid_in_iphy_xml(self, iphy_src, iphy_dst):  # noqa: C901
        """
        Changes preferredVlanId in iphy.xml accrding to __init__.py file.
        :param iphy_src: Source iphy.xml
        :param iphy_dst: Destination iphy.xml
        :return: None
        """
        tree = lxml.etree.parse(iphy_src)
        root = tree.getroot()
        tl = BuiltIn().get_variable_value("${tl}")
        number_of_vlans_to_change = len(tl.ues[0].preferred_vlans)
        if number_of_vlans_to_change == 1:
            for tag in chain(root.iter('{*}optlink')):
                for parameter in tag:
                    if 'preferredVlanId' in parameter.tag:
                        parameter.text = str(tl.ues[0].preferred_vlans[0].preferred_vlan_id).encode("utf-8").decode("utf-8")
        else:
            list_of_vlans = [tl.ues[0].preferred_vlans[idx].preferred_vlan_id for idx in range(number_of_vlans_to_change)]
            for tag in enumerate(chain(root.iter('{*}optlink'))):
                logger.console(tag)
                for parameter in tag[1]:
                    if 'preferredVlanId' in parameter.tag:
                        parameter.text = str(list_of_vlans[tag[0]]).encode("utf-8").decode("utf-8")

        tree.write(iphy_dst)

    def verify_scfc_object_parameter(self, scfc, dist, param, value):
        """
        Verifies that given parameter has given value.
        :param scfc: SCFC file to be checked
        :param dist: Distname to object
        :param param: Parameter name
        :param value: Expected value
        :return: bool
        """
        distname = '/'.join(dist)
        tree = lxml.etree.parse(scfc)
        root = tree.getroot()
        elem = root.find("*{*}managedObject[@distName=\"" + distname + "\"]/{*}p[@name=\"" + param + "\"]")
        if elem is not None:
            return elem.text == value
        else:
            return False

    def get_radios_name_from_iphy_xml(self, xml_path):
        """
        Method return name of radios in iphy xml file.
        :param xml_path: Path to iphy file with xml extension
        :return: list
        """
        tree = lxml.etree.parse(xml_path)
        root = tree.getroot()
        radiolist = []

        for radio in root.iter("productname"):
            radiolist.append(radio.text)
        return radiolist
